// GradientBackground — "Red Blue", made with the 21st.dev Gradient
// Builder and exported as live CSS (the builder's own Copy-CSS background,
// plus its soften-blur and grain passes). Zero dependencies: one <div> that
// fills its parent. Drop it behind your content:
// <div className="relative h-96"><GradientBackground className="absolute inset-0" /></div>
// Remix the source recipe (colors, mode, finish) in the editor:
// https://21st.dev/community/gradients/editor?from=4aee9fd8-6bfb-42f3-8b0e-c9ad4ecbfbbf
export function GradientBackground({ className }: { className?: string }) {
  return (
    <div
      aria-hidden="true"
      className={className}
      style={{
        position: "relative",
        overflow: "hidden",
        width: "100%",
        height: "100%",
        containerType: "size",
      }}
    >
      <div
        style={{
          position: "absolute",
        inset: 0,
        backgroundColor: "#DD2C2C",
        backgroundImage:
          "url(\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)' opacity='0.165'/></svg>\"), radial-gradient(circle at 50% 50%, rgba(0, 0, 0, 0) 52%, rgba(0, 0, 0, 0.384) 100%), radial-gradient(circle at 66.96% 42.71%, rgba(8, 29, 99, 1) 0%, rgba(8, 29, 99, 0.844) 14.04%, rgba(8, 29, 99, 0.5) 28.07%, rgba(8, 29, 99, 0.156) 42.11%, rgba(8, 29, 99, 0) 56.15%), radial-gradient(circle at 40.53% 70.28%, rgba(0, 81, 180, 1) 0%, rgba(0, 81, 180, 0.844) 13.51%, rgba(0, 81, 180, 0.5) 27.02%, rgba(0, 81, 180, 0.156) 40.54%, rgba(0, 81, 180, 0) 54.05%), radial-gradient(circle at 45.87% 23.93%, rgba(220, 44, 44, 1) 0%, rgba(220, 44, 44, 0.844) 11.5%, rgba(220, 44, 44, 0.5) 23%, rgba(220, 44, 44, 0.156) 34.5%, rgba(220, 44, 44, 0) 46%), radial-gradient(circle at 74.13% 75.93%, rgba(221, 44, 44, 1) 0%, rgba(221, 44, 44, 0.844) 17.19%, rgba(221, 44, 44, 0.5) 34.38%, rgba(221, 44, 44, 0.156) 51.56%, rgba(221, 44, 44, 0) 68.75%), radial-gradient(circle at 10.15% 39.91%, rgba(83, 0, 151, 1) 0%, rgba(83, 0, 151, 0.844) 15.44%, rgba(83, 0, 151, 0.5) 30.88%, rgba(83, 0, 151, 0.156) 46.31%, rgba(83, 0, 151, 0) 61.75%), radial-gradient(circle at 82.7% 24.05%, rgba(101, 0, 184, 1) 0%, rgba(101, 0, 184, 0.844) 15%, rgba(101, 0, 184, 0.5) 30%, rgba(101, 0, 184, 0.156) 45%, rgba(101, 0, 184, 0) 60%), radial-gradient(circle at 38.09% 90.99%, rgba(221, 44, 44, 1) 0%, rgba(221, 44, 44, 0.844) 16.23%, rgba(221, 44, 44, 0.5) 32.45%, rgba(221, 44, 44, 0.156) 48.68%, rgba(221, 44, 44, 0) 64.9%)",
        backgroundSize: "120px 120px, auto, auto, auto, auto, auto, auto, auto, auto",
        backgroundBlendMode: "overlay, normal, normal, normal, normal, normal, normal, normal, normal",
        }}
      />
      <svg
        aria-hidden="true"
        style={{
          position: "absolute",
          inset: 0,
          width: "100%",
          height: "100%",
          opacity: 0.165,
          mixBlendMode: "overlay",
        }}
      >
        <filter id="grain-4aee9fd8">
          <feTurbulence
            type="fractalNoise"
            baseFrequency="0.8"
            numOctaves="2"
            stitchTiles="stitch"
          />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter="url(#grain-4aee9fd8)" />
      </svg>
    </div>
  )
}

